BLUEPRINT_MAPPING = []

# A field's own selector is evaluated against the top-level page unless it
# has a FRAME_PATH entry — an ordered list of CSS selectors identifying each
# iframe from the top document down to the frame the field actually lives
# in. Shadow DOM needs no equivalent: Playwright's own selector engine
# pierces open shadow roots automatically for a plain CSS selector.
FRAME_PATHS = {
}


# Issue #84: best-effort numeric normalization for a "toNumber" transform —
# finds the first numeric-looking substring and normalizes its decimal
# separator to '.', stripping thousands separators/currency symbols. When
# both '.' and ',' appear, the rightmost one is treated as the decimal point
# (handles both "1.234,56" and "1,234.56"); a single separator appearing more
# than once is treated as a thousands separator and stripped; a single
# separator appearing exactly once is treated as the decimal point (so
# "12,99"/"12.99" both work, at the cost of a genuinely ambiguous
# single-occurrence case like "1.234" always being read as 1.234, never as
# 1234 — chain a regex-extract transform first if that's not what's wanted).
# Empty string if nothing numeric is found.
def _to_number(value):
    match = re.search(r"-?\d[\d.,]*", value)
    if not match:
        return ""
    raw = match.group(0)
    last_dot = raw.rfind(".")
    last_comma = raw.rfind(",")
    if last_dot != -1 and last_comma != -1:
        decimal_pos = max(last_dot, last_comma)
        integer_part = raw[:decimal_pos].replace(".", "").replace(",", "")
        fractional_part = raw[decimal_pos + 1:]
        normalized = f"{integer_part}.{fractional_part}"
    elif raw.count(",") > 1 or raw.count(".") > 1:
        normalized = raw.replace(",", "").replace(".", "")
    else:
        normalized = raw.replace(",", ".")
    try:
        numeric = float(normalized)
    except ValueError:
        return ""
    return str(int(numeric)) if numeric.is_integer() else str(numeric)


# Issue #205: safe, explicit type-conversion transforms -- unlike toNumber's
# best-effort heuristic extraction, these either produce a well-formed value
# or fall back to their own clearly defined "onError" behavior
# ("KeepOriginal" leaves the pre-conversion value untouched, "UseDefault"
# substitutes the transform's own configured "defaultValue") rather than
# silently guessing.
_DATE_FORMAT_TOKEN_PATTERNS = {"yyyy": r"(?P<yyyy>\d{4})", "mm": r"(?P<mm>\d{1,2})", "dd": r"(?P<dd>\d{1,2})"}


def _type_conversion_fallback(value, on_error, default_value):
    return default_value if on_error == "UseDefault" else value


def _to_integer(value, on_error, default_value):
    stripped = value.strip()
    if re.fullmatch(r"[+-]?\d+", stripped):
        return str(int(stripped))
    return _type_conversion_fallback(value, on_error, default_value)


def _to_boolean(value, on_error, default_value):
    normalized = value.strip().lower()
    if normalized in ("true", "1", "yes", "y"):
        return "True"
    if normalized in ("false", "0", "no", "n"):
        return "False"
    return _type_conversion_fallback(value, on_error, default_value)


# source_format is the same "{yyyy}"/"{mm}"/"{dd}" mini-template
# RangeSource.Format (RangeFormat.cs) already uses for ISO week/date
# parameters, compiled into a regex the same way (escape the literal
# template, then substitute each placeholder for its own capture group) so a
# format string valid on the companion side parses identically here. Also
# rejects a structurally-matching but non-existent calendar date (e.g.
# "2026-02-30") via date()'s own ValueError, not just a pattern match.
def _to_date(value, source_format, on_error, default_value):
    pattern = re.escape(source_format)
    for token, token_pattern in _DATE_FORMAT_TOKEN_PATTERNS.items():
        pattern = pattern.replace(re.escape("{" + token + "}"), token_pattern)
    match = re.fullmatch(pattern, value.strip())
    if match:
        try:
            return date(int(match.group("yyyy")), int(match.group("mm")), int(match.group("dd"))).isoformat()
        except ValueError:
            pass
    return _type_conversion_fallback(value, on_error, default_value)


# Issue #234: strict price/currency conversion. number_format is one of
# ToCurrencyTransform.SupportedFormats, each written as its own example
# amount — its first punctuation mark is the thousands separator, its last
# the decimal separator (a space format also accepts no-break/narrow
# no-break spaces, the apostrophe format a typographic apostrophe). Finds
# the first number in the value (a separator only counts when a digit
# follows, so a trailing "." or "," after the amount is never swallowed),
# requires it to match the format strictly (thousands groups of exactly
# three digits, at most one decimal separator), and keeps the fraction
# digits exactly as scraped — no float rounding. Mirrored by
# toCurrencyPreview in extension/popup/field-transforms.js.
_CURRENCY_FORMATS = {
    "1.234,56": (",", "."),
    "1,234.56": (".", ","),
    "1 234,56": (",", "   "),
    "1'234.56": (".", "'’"),
}


def _to_currency(value, number_format, on_error, default_value):
    decimal_sep, thousands_seps = _CURRENCY_FORMATS.get(number_format, _CURRENCY_FORMATS["1.234,56"])
    candidate = re.search(r"[+-]?[0-9](?:[0-9]|[" + re.escape(decimal_sep + thousands_seps) + r"](?=[0-9]))*", value)
    if candidate:
        thousands = "[" + re.escape(thousands_seps) + "]"
        match = re.fullmatch(
            r"([+-]?)([0-9]{1,3}(?:" + thousands + r"[0-9]{3})+|[0-9]+)(?:" + re.escape(decimal_sep) + r"([0-9]+))?",
            candidate.group(0),
        )
        if match:
            integer = str(int(re.sub(thousands, "", match.group(2))))
            sign = "-" if match.group(1) == "-" else ""
            return sign + integer + ("." + match.group(3) if match.group(3) else "")
    return _type_conversion_fallback(value, on_error, default_value)


# Applies a field's ordered transform chain — each step's output feeds the
# next step's input, in the order the user configured them in.
# Issue #206: looks up another field's own already-computed value for
# CombineFieldsTransform/SplitFieldTransform. `siblings` is whatever
# representation the calling shape already has on hand at this point in
# extraction — a plain dict for flat/API-flat mode's in-progress row, or the
# in-construction parent ET.Element for container/API-tree mode (only that
# element's own direct children are considered, i.e. only siblings under the
# very same immediate parent group — see ScrapingPlanValidator's
# ValidateFieldTransformOrdering for why this is guaranteed to already be
# populated for a valid config). Missing/not-yet-computed simply resolves to
# "" rather than raising, the same "don't fail the whole row/element over
# one field" spirit every other transform here already follows.
def _resolve_transform_sibling(siblings, name):
    if siblings is None:
        return ""
    if isinstance(siblings, dict):
        return siblings.get(name, "")
    found = siblings.find(name)
    return (found.text or "") if found is not None else ""


def _apply_transforms(value, transforms, siblings=None):
    for t in transforms:
        kind = t["kind"]
        if kind == "trim":
            value = value.strip()
        elif kind == "regexExtract":
            match = re.search(t["pattern"], value)
            if match:
                try:
                    value = match.group(t.get("group", 0)) or ""
                except (IndexError, re.error):
                    value = ""
            else:
                value = ""
        elif kind == "replace":
            value = value.replace(t["find"], t["replacement"])
        elif kind == "toNumber":
            value = _to_number(value)
        elif kind == "toInteger":
            value = _to_integer(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toBoolean":
            value = _to_boolean(value, t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toDate":
            value = _to_date(value, t.get("sourceFormat", "{yyyy}-{mm}-{dd}"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "toCurrency":
            value = _to_currency(value, t.get("format", "1.234,56"), t.get("onError", "KeepOriginal"), t.get("defaultValue", ""))
        elif kind == "combineFields":
            value = t.get("separator", " ").join(_resolve_transform_sibling(siblings, n) for n in t.get("sourceFieldNames", []))
        elif kind == "splitField":
            parts = _resolve_transform_sibling(siblings, t.get("sourceFieldName", "")).split(t.get("separator", " "))
            idx = t.get("index", 0)
            value = parts[idx] if 0 <= idx < len(parts) else ""
    return value


def _resolve_frame_locator(page, frame_path):
    scope = page
    for frame_selector in frame_path:
        scope = scope.frame_locator(frame_selector)
    return scope


# Used by the WaitFor/Fill/Click/Scroll action fragments rendered into the
# scrape() body below (one per playwright_*_step.py.j2 template) — a plain
# page.locator(selector) when frame_path is unset, a frame-scoped Locator
# otherwise. Page has .locator() too, so _resolve_frame_locator(page, [])
# returning page unchanged already makes this uniform without a separate
# branch here.
def _resolve_locator(page, selector, frame_path):
    return _resolve_frame_locator(page, frame_path or []).locator(selector)


# ElementHandle (from query_selector_all) and Locator (from a FrameLocator
# chain) expose the same .text_content()/.get_attribute() methods, so the
# extraction loop below doesn't need to know or care which one it got — only
# resolving "selector string" -> "list of element-like objects" differs.
def _resolve_elements(page, selector, frame_path):
    if not frame_path:
        return page.query_selector_all(selector)
    return _resolve_frame_locator(page, frame_path).locator(selector).all()




def _extract_page_rows(page):
    # Issue #206 follow-up: see scraper.py.j2's own identical doc comment —
    # a derived (combineFields/splitField) field has no selector of its own
    # and is computed separately below, once per row.
    columns = {name: _resolve_elements(page, sel, FRAME_PATHS.get(name)) for name, sel in SELECTORS.items() if sel}
    n = max((len(v) for v in columns.values()), default=0)

    rows = []
    for i in range(n):
        row = {}
        for name in SELECTORS:
            if name not in columns:
                row[name] = _apply_transforms("", TRANSFORMS.get(name, []), row)
                continue
            elements = columns[name]
            if i < len(elements):
                attr = ATTRIBUTES.get(name)
                raw_value = (elements[i].get_attribute(attr) or "") if attr else (elements[i].text_content() or "").strip()
                value = _apply_transforms(raw_value, TRANSFORMS.get(name, []), row)
                # Issue #213/#214: see scraper.py.j2's own identical doc
                # comment — applied after transforms, only ever True for an
                # attribute-mode field (validated upstream).
                if attr and DOWNLOAD.get(name) and value:
                    value = _download_resource(page, value, MAX_DOWNLOAD_SIZE.get(name), ALLOWED_CONTENT_TYPES.get(name))
                row[name] = value
            else:
                row[name] = ""
        rows.append(row)
    return rows






def scrape(url):
    with sync_playwright() as p:
        browser = p.chromium.launch()
        page = browser.new_page()
        _goto_checked(page, url)

        rows = []
        page_number = 1
        while True:
            page_rows = _extract_page_rows(page)
            if not page_rows:
                break
            rows.extend(page_rows)

            break

        browser.close()
        return rows


# Issue #319: a failed page request ends in one clean, actionable
# "ERROR: <what> to <url> failed: <detail>" line on stderr and a dedicated
# exit code instead of a raw requests/Playwright traceback — the same shape
# API mode has had since Issue #220 (PythonScriptVerifier.CleanScriptError
# turns such a line into /generate's error text). The hints say what to do
# about the status instead of only repeating it.
EXIT_REQUEST_FAILED = 7


def _request_failed(what, url, detail):
    print(f"ERROR: {what} to {url} failed: {detail}", file=sys.stderr)
    sys.exit(EXIT_REQUEST_FAILED)


def _http_error_detail(status_code):
    if status_code in (401, 403):
        reason = "Unauthorized" if status_code == 401 else "Forbidden"
        return (f"HTTP {status_code} ({reason}). The site refuses this script — it either requires a login "
                f"or blocks automated requests. If a login is needed, use the Browser engine with a login flow "
                f"or send a custom request header (e.g. Cookie or Authorization).")
    if status_code == 404:
        return "HTTP 404 (Not Found). The page doesn't exist (any more) — check the start URL."
    if status_code == 429:
        return ("HTTP 429 (Too Many Requests). The site is rate-limiting this script — enable "
                "\"Pause between requests\" or try again later.")
    if status_code >= 500:
        return (f"HTTP {status_code}. The site's server reported an error — this is usually temporary; "
                f"try again later or enable \"Retry on transient errors\".")
    return f"HTTP {status_code}."


# Navigates to `url`. Unlike requests, page.goto() doesn't raise on an HTTP
# error status (it hands back the error page, which then silently yields "no
# data"), and a navigation timeout/network error is a Playwright exception —
# both become one clean error line instead. A page.goto() that returns None
# (e.g. a same-document navigation) has no status to check.
def _goto_checked(page, url):
    try:
        response = page.goto(url, wait_until="load", timeout=30000)
    except Exception as e:
        # Playwright's message starts with the useful part ("Page.goto:
        # net::ERR_CONNECTION_REFUSED at ..." / "Timeout 30000ms exceeded");
        # the rest is a multi-line call log.
        reason = (str(e).splitlines() or [e.__class__.__name__])[0]
        _request_failed("Navigation", url, f"could not load the page ({reason}).")
    if response is not None and response.status >= 400:
        _request_failed("Navigation", url, _http_error_detail(response.status))
    return response




def main():
    all_urls = URLS
    data = []
    for url in all_urls:
        data.extend(scrape(url))
    written_data = data
    # Issue #191: BLUEPRINT_MAPPING, when set, takes over the write-time
    # remap entirely instead of FIELD_OUTPUT_NAMES — it already fully
    # determines the output's column names *and* order, and any source
    # field with no entry in it is dropped rather than written under its
    # own name. Issue #178: otherwise, a no-op remap when no field was
    # renamed via the external config (FIELD_OUTPUT_NAMES is then empty) —
    # `data` itself stays keyed by the original field names throughout
    # either way, since hardening/change detection below still need to look
    # fields up by those original names.
    if BLUEPRINT_MAPPING:
        output_rows = [{m["target"]: row.get(m["source"], "") for m in BLUEPRINT_MAPPING} for row in written_data]
        output_fieldnames = [m["target"] for m in BLUEPRINT_MAPPING]
    else:
        # Issue #206 follow-up: a HiddenFromOutput field is dropped here —
        # at the write-time projection only, same as FIELD_OUTPUT_NAMES —
        # never from `data` itself, which hardening/change detection (and
        # any combineFields/splitField transform referencing it) still need
        # to see under its real name.
        output_rows = [
            {FIELD_OUTPUT_NAMES.get(k, k): v for k, v in row.items() if k not in HIDDEN_FIELD_NAMES}
            for row in written_data
        ]
        output_fieldnames = [FIELD_OUTPUT_NAMES.get(name, name) for name in SELECTORS.keys() if name not in HIDDEN_FIELD_NAMES]
    with open(OUTPUT_PATH, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=output_fieldnames)
        writer.writeheader()
        writer.writerows(output_rows)
    print(f"Done — {len(data)} rows written to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
